"""Actual P1 cone-globalized physical Newton in a rigid-enriched Ritz space.
The Ritz space restricts SEARCH only; full physical KKT decides qualification.
No physical penalty, removed row, or nonlinear support substitution.
"""
import sys,json,time,shutil
import numpy as np
from scipy import sparse
from scipy.linalg import qr
import pyamg,osqp
from baseline_registry import ROOT,REPO,ref,dump

def main():
 t=time.monotonic();assert not(ROOT/'runtime/STOP').exists();out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'producer.py')
 src=ROOT/'validation/integrated/primaryP1_finite_null_step1/summary.json';s=json.loads(src.read_text());parent=json.loads((REPO/s['physical_source']['path']).read_text());p=np.load(REPO/s['problem']['path']);P=sparse.load_npz(REPO/s['physical_P']['path']);A=sparse.load_npz(REPO/s['physical_A']['path']);x=np.load(REPO/s['output']['path'])['after_x'];null=json.loads((REPO/s['source']['path']).read_text());R=np.load(REPO/null['output']['path'])['R'];D=p['D'].copy();ray=json.loads((REPO/parent['source']['path']).read_text());D[-1]=ray['direction_scaling_gamma'];E=p['E'];q=p['q'];lo=p['lower'];eq=np.isfinite(p['upper'])&(lo==p['upper']);ineq=~eq;sl=A@x-lo;active=np.union1d(np.flatnonzero(eq),np.flatnonzero(ineq&(sl<=1e-10)));force=P@x+q;Ps=(sparse.diags(D)@P@sparse.diags(D)).tocsr();As=(sparse.diags(E)@A@sparse.diags(D)).tocsr();near=R/D[:,None];near/=np.maximum(np.linalg.norm(near,axis=0),1e-30);Pr=Ps+sparse.diags(1e-6*np.maximum(Ps.diagonal(),1.));ml=pyamg.smoothed_aggregation_solver(Pr,B=near,symmetry='symmetric',max_levels=10,max_coarse=120,presmoother=('gauss_seidel',{'sweep':'symmetric'}),postsmoother=('gauss_seidel',{'sweep':'symmetric'}),coarse_solver='pinv');M=ml.aspreconditioner(cycle='V')
 # Rigid modes explicitly retained BEFORE elastic search enrichment. QR here
 # removes only duplicate search vectors; it never reduces the contact cone.
 Q,_=np.linalg.qr(near);vectors=[M@(D*force)]
 for row in active:
  assert not(ROOT/'runtime/STOP').exists()
  if time.monotonic()-t>230:break
  vectors.append(M@As.getrow(row).toarray().ravel())
 W=np.column_stack(vectors);W-=Q@(Q.T@W);W-=Q@(Q.T@W);U,T,piv=qr(W,mode='economic',pivoting=True);diag=abs(np.diag(T));rank=int(sum(diag>max(diag[0]*1e-12,1e-14)));Z=np.column_stack([Q,U[:,:rank]]);V=D[:,None]*Z;H=V.T@(P@V);H=.5*(H+H.T);g=V.T@force;B=np.asarray(A@V);rs=1/np.maximum(np.max(abs(B),axis=1),1e-15);scale=max(float(np.max(abs(g))),1e-15);solver=osqp.OSQP();solver.setup(P=sparse.csc_matrix(H/scale),q=g/scale,A=sparse.csc_matrix(rs[:,None]*B),l=-rs*sl,u=np.where(eq,-rs*sl,np.inf),eps_abs=1e-10,eps_rel=1e-10,max_iter=20000,time_limit=max(1.,280-(time.monotonic()-t)),polishing=True,verbose=False,scaled_termination=False);r=solver.solve();c=r.x;y=scale*rs*r.y;dx=V@c;gt=float(force@dx);curv=float(dx@(P@dx));alpha=min(1.,-gt/curv) if gt<0 and curv>0 else 1.;trial=x+alpha*dx;end=A@trial-lo;before=float(.5*x@(P@x)+q@x);after=float(.5*trial@(P@trial)+q@trial);pr=max(float(np.max(np.maximum(-end[ineq],0))),float(np.max(abs(end[eq]))));accepted=bool(np.all(np.isfinite(trial)) and pr<1e-10 and gt<0 and after<=before+1e-4*alpha*gt);res=P@trial+q+A.T@y;metrics=dict(primal_mm=pr,stationarity_N=float(np.max(abs(res))),gauge_N=float(np.max(abs(y[eq]))),RootY_gamma_stationarity_N=float(abs(y[2175])),sign_N=float(np.max(np.maximum(y[ineq],0))),complementarity_Nmm=float(np.max(abs(end[ineq]*y[ineq]))),reduced_stationarity=float(np.max(abs(V.T@res))),physical_directional_work_Nmm=gt,physical_curvature_Nmm=curv,objective_before_Nmm=before,objective_after_Nmm=after,alpha=alpha,search_H_min_eigenvalue=float(np.linalg.eigvalsh(H)[0]));qualified=accepted and all(metrics[k]<1e-8 for k in ['stationarity_N','gauge_N','RootY_gamma_stationarity_N','sign_N','complementarity_Nmm'])
 np.savez_compressed(out/'ritz.npz',before_x=x,V=V,H=H,g=g,B=B,coefficients=c,dual=y,direction=dx,proposed_x=trial,after_x=trial if accepted else x,physical_residual=res,slack=end,active=active)
 result=dict(status='ACTUAL_P1_CONIC_RITZ_NEWTON_LINEAR_STEP_NOT_EQUILIBRIUM' if accepted else 'ACTUAL_P1_CONIC_RITZ_NEWTON_REJECTED',candidate=s['candidate'],source=ref(src),source_field=parent['source_field'],physical_P=s['physical_P'],physical_A=s['physical_A'],problem=s['problem'],producer=ref(out/'producer.py'),output=ref(out/'ritz.npz'),rigid_modes=R.shape[1],retained_rigid_modes=Q.shape[1],search_dimension=V.shape[1],all_original_rows=A.shape[0],solver_status=r.info.status,solver_iterations=r.info.iter,metrics=metrics,physical_KKT_qualified=bool(qualified),accepted_linear_steps=int(accepted),actual_support_updates=0,accepted_equilibria=0,physical_regularization=0.,newly_qualified_system_gate_ids=[],whole_system_release=False,elapsed_s=time.monotonic()-t,limitations=['Physical-P Ritz minimization is a SEARCH approximation. All37 rigid modes and all2208 finite-gap rows retained. Reduced stationarity does not certify full equilibrium; full force/gauge/dual checks remain mandatory.','AMG shift and OSQP sigma belong only to numerical search; neither alters saved original P/q. No eigenvalue clipping, gamma penalty, row deletion, Base cancellation or nonlinear update. One bounded reduced QP, not retry of failed98row equality Newton.']);dump(out/'summary.json',result);print(json.dumps(result));raise SystemExit(0 if accepted else 2)
if __name__=='__main__':main()
